export function parseDuration(text) {
  const match = /^(\d+)m$/.exec(text);
  if (!match) throw new Error(`bad duration: ${text}`);
  return Number(match[1]) * 60;
}

import { parseDuration } from '../src/duration.js';
const cases = [['5m', 300], ['1h30m', 5400], ['90s', 90], ['2h', 7200], ['1h0m5s', 3605]];
for (const [input, expected] of cases) {
  const actual = parseDuration(input);
  if (actual !== expected) { console.error(`parseDuration(${input}) = ${actual}, expected ${expected}`); process.exit(1); }
}

